  "attribution": "Thrasymachus (20260102-001919)",
  "title": "Git Methodology & Metagit Synchronization",
  "description": "Rules for repository management, security, and recursive synchronization.",
  "values": [
    {
      "name": "Recursive Synchronization Policy",
      "rule": "Sync a multi-git filesystem by committing from the child repository up to the root.",
      "rationale": "Repositories are logically isolated and ignored by each other via .gitignore. Linkage is maintained solely by the Orchestrator through the metagit_commit wrapper, which treats parents as Object Gits (passthroughs) for nested subjects."
    },
    {
      "name": "Mandatory Commit Wrapper",
      "rule": "All commits must be executed via the \"metagit_commit.py\" wrapper service (located in meta-root).",
      "rationale": "Enforces identity verification, secret scanning (detect-secrets), and forensic traceability."
    },
    {
      "name": "Git Faithful Protocol",
      "rule": "The agent must ALWAYS ask for explicit user permission before creating a new branch in any memory repository.",
      "rationale": "Protects the firm's identity and history from unsanctioned divergence."
    },
    {
      "name": "Security Remediation",
      "rule": "If a secret is committed, the agent must immediately REPORT the violation and required remediation steps, then perform a Total Halt to await user feedback.",
      "rationale": "Altering history is a high-impact metabolic act that requires explicit user steering and consensus."
    },
    {
      "name": "Submodule Commit Context",
      "rule": "Commit operations for submodules must be executed from within the submodule's directory.",
      "rationale": "Ensures the commit is registered in the correct .git database."
    }
  ]
}

